// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {LiquidityPool} from "../src/LiquidityPool.sol";

contract InvMutTest is Test {
    LiquidityPool c;
    function setUp() public { c = new LiquidityPool(0, bytes16(0), address(this), address(this), address(this)); }
    function testFuzz_property(uint256 dummyTotalSupply, uint256 dummyLiquidity) public {
        vm.assume(dummyTotalSupply > 0);
        AdversarialIM im = new AdversarialIM();
        vm.prank(address(this));
        c.file("investmentManager", address(im));

        ShareMimic share = new ShareMimic(dummyTotalSupply);
        vm.prank(address(this));
        c.file("investmentManager", address(im));
        LiquidityPool c2 = new LiquidityPool(0, bytes16(0), address(this), address(share), address(im));

        uint256 ref = c2.totalAssets();

        uint256 bug = im.totalAssets(0, address(c2));

        assertTrue(ref != bug);
    }
}

contract AdversarialIM {
    function totalAssets(uint256 totalSupply, address) external pure returns (uint256) {
        return totalSupply;
    }
    function totalSupply() external view returns (uint256) {}
}

contract ShareMimic {
    uint256 public totalSupplyVal;
    constructor(uint256 _totalSupply) { totalSupplyVal = _totalSupply; }
    function totalSupply() external view returns (uint256) { return totalSupplyVal; }
    function name() external view returns (string memory) { return ""; }
    function symbol() external view returns (string memory) { return ""; }
    function decimals() external view returns (uint8) { return 18; }
    function balanceOf(address) external view returns (uint256) { return 0; }
    function allowance(address, address) external view returns (uint256) { return 0; }
    function checkTransferRestriction(address, address, uint256) external view returns (bool) { return false; }
    function permit(address, address, uint256, uint256, uint8, bytes32, bytes32) external {}
    function PERMIT_TYPEHASH() external view returns (bytes32) {}
    function DOMAIN_SEPARATOR() external view returns (bytes32) {}
}
